'use strict';
// Jambix central service -- which class a spell belongs to, per game, read
// off the clients' own tables: scripts/jambix_aio/modules/pvp_data.lua
// (generated by tools/jcheck/pvp_extract.js, the same file the plugin's
// state.own reads). A name exactly one class has; PET, RACIAL and a name two
// classes share give none. The trust screen's repair (trust.js) asks it
// which names in an old record's "used" were never that class's.

const fs = require('fs');
const path = require('path');

const FILE = path.join(__dirname, '..', '..', 'scripts', 'jambix_aio', 'modules', 'pvp_data.lua');

/** { forever: { name: class|false }, vanilla: {...} } from the generated Lua's fixed layout. */
function parse(text) {
    const out = {};
    let half = null, cls = null;
    for (const line of String(text).split(/\r?\n/)) {
        let m;
        if ((m = line.match(/^ {4}(\w+) = \{/))) { half = m[1]; out[half] = out[half] || {}; cls = null; continue; }
        if ((m = line.match(/^ {12}([A-Z]+) = \{/))) { cls = m[1]; continue; }
        if (half && cls && (m = line.match(/^ {16}\["(.+?)"\] = \{/))) {
            if (cls === 'PET' || cls === 'RACIAL') continue;
            const t = out[half];
            const name = m[1];
            if (t[name] === undefined) t[name] = cls;
            else if (t[name] !== cls) t[name] = false;
        }
    }
    return out;
}

let cache = null;
function load(file) {
    if (file) return parse(fs.readFileSync(file, 'utf8'));
    if (!cache) {
        try { cache = parse(fs.readFileSync(FILE, 'utf8')); } catch (e) { cache = {}; }
    }
    return cache;
}

/** The class a spell belongs to in a game's client ("Forever", else the Era tables), or null. */
function ownerOf(game, name, tables) {
    const all = tables || load();
    const half = all[String(game) === 'Forever' ? 'forever' : 'vanilla'] || {};
    return half[name] || null;
}

module.exports = { parse, load, ownerOf, FILE };
